    sell_book = []  # List of (price, arrival_time, id, qty) sorted by price asc, then arrival_time asc

    order_map = {}  # id -> (side, price, arrival_time, qty) for tracking resting orders
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, arr_time, qty = order_map[order_id]
                del order_map[order_id]

                # Remove from appropriate book
                if side == 'buy':
                    buy_book[:] = [(p, at, oid, q) for p, at, oid, q in buy_book if oid != order_id]
                else:
                    sell_book[:] = [(p, at, oid, q) for p, at, oid, q in sell_book if oid != order_id]

